const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function supplementCheckReady(quality,{current=true}={}){const check=quality?.supplementCheck;return current&&quality?.stale!==true&&quality?.coverage?.complete===true&&check?.phase==='final'&&check?.version===1&&check.status==='final_ready'&&check.coverage?.complete===true&&check.coverage.total>0&&check.coverage.checked===check.coverage.total&&check.items?.length===check.coverage.total&&check.items.every(row=>['sufficient','not_required'].includes(row.status));}
export function supplementCheckPanel(report,{stale=false}={}){
 const labels={checking:'正在检查补充资料',needs_materials:'资料仍有缺项',materials_ready:'资料已齐，正在完善正文',final_ready:'本次资料完整性检查已通过',unavailable:'检查尚未完成'};
 const title=stale?'内容或资料已更新，需要重新检查':labels[report?.status]||'尚未进行补充资料检查';
 return `<section class="supplement-check-panel" aria-label="补充内容检查"><header><strong>补充内容检查</strong><span role="status">${esc(title)}</span></header>${report?`<p>已检查 ${Number(report.coverage?.checked)||0} / ${Number(report.coverage?.total)||0} 项${report.checkedAt?' · '+esc(new Date(report.checkedAt).toLocaleString()):''}</p>${report.reason?`<p>${esc(report.reason)}</p>`:''}<ul class="supplement-check-items" tabindex="0" aria-label="资料完整性检查明细">${(report.items||[]).map(row=>`<li><b>${row.status==='missing'?'待补充':'已检查'} · ${esc(row.title)}</b><p>${esc(row.requirement)}：${esc(row.reason)}</p>${row.missing?.length?`<p>请提供：${row.missing.map(esc).join('；')}</p>`:''}${row.evidence?.length?`<details><summary>查看对应资料</summary>${row.evidence.map(proof=>`<p>${esc(proof.name)}：${esc(proof.quote)}</p>`).join('')}</details>`:''}</li>`).join('')}</ul>`:'<p>点击“保存材料并自动完善”，系统会读取资料、逐项检查缺口，并在完善正文后复查。通过检查后才能生成终稿。</p>'}<small>检查针对本次提交的资料与要求；格式和页面另行检查。</small></section>`;
}
